effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmBubble(vec2 uv, float cols, float seed, float t, float sizePx, float wobble, float aspect, float gate, float refractAmt, inout vec2 refractOffset){
vec2 p = uv * vec2(cols, cols / max(aspect * 1.25, 0.6));
vec2 cell = floor(p);
float h = gmHash2(cell + seed);
if (h < gate) return 0.0;
vec2 f = fract(p) - 0.5;
float h2 = gmHash2(cell * 4.7 + seed * 9.1);
float h3 = gmHash2(cell * 8.3 + seed * 2.9);
float rise = fract(-t * (0.4 + h2 * 0.7) + h * 13.0);
float sway = sin(t * (1.0 + h2 * 2.0) + h * 6.2831) * 0.28 * wobble;
float rad = (0.10 + 0.22 * h2) * sizePx;
float mx = max(0.5 - rad, 0.05);
vec2 pos = clamp(vec2((h3 - 0.5) * 0.7 + sway, rise - 0.5), vec2(-mx), vec2(mx));
float d = length(f - pos);
if (d > rad) return 0.0;
float inside = 1.0 - smoothstep(rad * 0.92, rad, d);
float rim = smoothstep(rad * 0.55, rad * 0.97, d) * inside;
vec2 nrm = (f - pos) / max(rad, 1e-4);
float spec = pow(max(dot(nrm, normalize(vec2(-0.5, 0.62))), 0.0), 24.0);
refractOffset += nrm * rad * refractAmt * 0.25 * inside;
return inside * 0.12 + rim * rimBright + spec * 0.9;
}
void main(){
vec2 uv = acScreenNorm;
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
float gate = 1.0 - bubAmount * 0.01;
float t = acTime * bubSpeed;
vec2 refr = vec2(0.0);
float b1 = gmBubble(uv, 10.0, 3.0, t, bubSize * 1.5, bubWobble, aspect, gate, bubRefract, refr);
float b2 = gmBubble(uv, 16.0, 31.0, t * 1.25, bubSize, bubWobble * 1.3, aspect, gate, bubRefract, refr);
float b3 = gmBubble(uv, 26.0, 77.0, t * 1.6, bubSize * 0.6, bubWobble * 1.6, aspect, gate, bubRefract, refr);
vec2 suv = clamp(uv + refr, 0.0, 1.0);
vec4 src = texture2DCv(inputImg.texture, suv);
float shade = (b1 * 1.2 + b2 + b3 * 0.7);
vec3 col = src.rgb + rimColor.rgb * shade * bubOpacity;
gl_FragColor = vec4(col * src.a, src.a);
}
